WITH UserPostStats AS (SELECT u.Id AS UserId, u.DisplayName, COUNT(p.Id) AS TotalPosts, SUM(CASE WHEN p.PostTypeId = 1 THEN 1 ELSE 0 END) AS TotalQuestions, SUM(CASE WHEN p.PostTypeId = 2 THEN 1 ELSE 0 END) AS TotalAnswers, COALESCE(SUM(vt.VoteValue), 0) AS TotalVotes FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId LEFT JOIN (SELECT PostId, SUM(CASE WHEN VoteTypeId = 2 THEN 1 WHEN VoteTypeId = 3 THEN -1 ELSE 0 END) AS VoteValue FROM Votes GROUP BY PostId) AS vt ON p.Id = vt.PostId GROUP BY u.Id, u.DisplayName), TopUsers AS (SELECT UserId, DisplayName, TotalPosts, TotalQuestions, TotalAnswers, TotalVotes, ROW_NUMBER() OVER (ORDER BY TotalVotes DESC NULLS FIRST) AS Rank FROM UserPostStats) SELECT u.Id AS UserId, u.DisplayName, t.TotalPosts, t.TotalQuestions, t.TotalAnswers, t.TotalVotes, CASE WHEN t.Rank <= 10 THEN 'Top Contributor' ELSE 'Regular Contributor' END AS ContributorType, COALESCE((SELECT GROUP_CONCAT(b.Name, ', ') FROM Badges AS b WHERE b.UserId = u.Id), 'No Badges') AS Badges, (SELECT COUNT(c.Id) FROM Comments AS c WHERE c.UserId = u.Id) AS TotalComments FROM TopUsers AS t JOIN Users AS u ON t.UserId = u.Id WHERE u.Reputation > 100 ORDER BY TotalVotes DESC NULLS FIRST, u.CreationDate ASC